[numthreads(8, 8, 1)]
void CSWindDebugFlatten(uint3 id : SV_DispatchThreadID)
{
    uint sliceX = id.x / VolumeSize.x;
    uint sliceY = id.y / VolumeSize.z; 
    uint sliceIdx = sliceY * DebugGridCols + sliceX;

    if (sliceIdx < (uint)VolumeSize.y)
    {
