            color = float3(0.8, 0.8, 0.8);

        WindDebugTexture2D[id.xy] = float4(color, 1.0);
    }
    else
    {
        // 越界留白区域填充黑色
        WindDebugTexture2D[id.xy] = float4(0, 0, 0, 1.0);
    }
}
